-- Whiskyeksperten.dk import (staging) - 509 rom
-- Kilde: whiskyeksperten.dk/rom (?p=1-9), produktkort med navn, volumen, ABV, lagerstatus, pris og billede, 2026-11-08
-- Beskrivelser: butikkens produktsider er JS-renderede uden server-side beskrivelse -> NULL.
-- Koer: 1) hele filen, 2) SELECT * FROM import_shop('Whiskyeksperten', 'https://www.whiskyeksperten.dk', 'stg_whiskyeksperten_dk', 'Rom');

DROP TABLE IF EXISTS stg_whiskyeksperten_dk;
CREATE TABLE stg_whiskyeksperten_dk (
    name TEXT, url TEXT, price_dkk NUMERIC, in_stock BOOLEAN,
    volume_cl NUMERIC, abv NUMERIC, image_url TEXT, description TEXT,
    scraped_at TIMESTAMPTZ
);

-- Kontrol: forventer total=509, paa_lager=427, udsolgt=82, uden volumen/abv=0
SELECT COUNT(*) AS total,
       COUNT(*) FILTER (WHERE in_stock) AS paa_lager,
       COUNT(*) FILTER (WHERE NOT in_stock) AS udsolgt,
       COUNT(*) FILTER (WHERE volume_cl IS NULL) AS uden_volumen,
       COUNT(*) FILTER (WHERE abv IS NULL) AS uden_abv,
       MIN(price_dkk) AS billigste, MAX(price_dkk) AS dyreste
FROM stg_whiskyeksperten_dk;
